export default JSON.parse("{\"workId\":\"xunzi\",\"chapter\":{\"id\":\"xunzi_ch-23\",\"workId\":\"xunzi\",\"order\":23,\"title\":\"性惡\",\"difficulty\":4,\"estimatedMinutes\":13,\"passageIds\":[\"xunzi_ch-23_p-1\",\"xunzi_ch-23_p-2\",\"xunzi_ch-23_p-3\",\"xunzi_ch-23_p-4\",\"xunzi_ch-23_p-5\",\"xunzi_ch-23_p-6\",\"xunzi_ch-23_p-7\",\"xunzi_ch-23_p-8\",\"xunzi_ch-23_p-9\",\"xunzi_ch-23_p-10\",\"xunzi_ch-23_p-11\",\"xunzi_ch-23_p-12\",\"xunzi_ch-23_p-13\",\"xunzi_ch-23_p-14\",\"xunzi_ch-23_p-15\",\"xunzi_ch-23_p-16\",\"xunzi_ch-23_p-17\",\"xunzi_ch-23_p-18\",\"xunzi_ch-23_p-19\",\"xunzi_ch-23_p-20\",\"xunzi_ch-23_p-21\",\"xunzi_ch-23_p-22\",\"xunzi_ch-23_p-23\",\"xunzi_ch-23_p-24\"],\"tags\":[\"儒家\",\"性惡論\",\"禮樂\"]},\"passages\":[{\"id\":\"xunzi_ch-23_p-1\",\"chapterId\":\"xunzi_ch-23\",\"order\":1,\"canonicalText\":\"人之性惡，其善者偽也。今人之性，生而有好利焉，順是，故爭奪生而辭讓亡焉；生而有疾惡焉，順是，故殘賊生而忠信亡焉；生而有耳目之欲，有好聲色焉，順是，故淫亂生而禮義文理亡焉。然則從人之性，順人之情，必出於爭奪，合於犯分亂理，而歸於暴。故必將有師法之化，禮義之道，然後出於辭讓，合於文理，而歸於治。用此觀之，人之性惡明矣，其善者偽也。\",\"sentenceIds\":[\"xunzi_ch-23_p-1_s-1\",\"xunzi_ch-23_p-1_s-2\",\"xunzi_ch-23_p-1_s-3\",\"xunzi_ch-23_p-1_s-4\",\"xunzi_ch-23_p-1_s-5\",\"xunzi_ch-23_p-1_s-6\",\"xunzi_ch-23_p-1_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"人的性惡，他的善的人或事物偽啊。今人的性，生而且有好利焉，順是，所以爭奪生而且辭讓亡焉；生而且有疾惡焉，順是，所以殘賊生而且忠信亡焉；生而且有耳目的欲，有好聲色焉，順是，所以淫亂生而且禮正義道義道品德修養規程正義道義文理亡焉。然則從人的性，順人的情，必出於爭奪，合於犯分亂理，而且歸於暴。所以必將有師國家典章法度的化，禮正義道義道品德修養規程正義道義的道，然後出於辭讓，合於文理，而且歸於治。用此觀的，人的性惡明矣，他的善的人或事物偽啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「人之性惡，其善者偽也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「人之性惡，其善者偽也。今人之性，生而有好利焉，順是，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-2\",\"chapterId\":\"xunzi_ch-23\",\"order\":2,\"canonicalText\":\"故枸木必將待檃栝、烝矯然後直；鈍金必將待礱厲然後利；今人之性惡，必將待師法然後正，得禮義然後治，今人無師法，則偏險而不正；無禮義，則悖亂而不治，古者聖王以人性惡，以為偏險而不正，悖亂而不治，是以為之起禮義，製法度，以矯飾人之情性而正之，以擾化人之情性而導之也，始皆出於治，合於道者也。今人之化師法，積文學，道禮義者為君子；縱性情，安恣睢，而違禮義者為小人。用此觀之，人之性惡明矣，其善者偽也。\",\"sentenceIds\":[\"xunzi_ch-23_p-2_s-1\",\"xunzi_ch-23_p-2_s-2\",\"xunzi_ch-23_p-2_s-3\",\"xunzi_ch-23_p-2_s-4\",\"xunzi_ch-23_p-2_s-5\",\"xunzi_ch-23_p-2_s-6\",\"xunzi_ch-23_p-2_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以枸木必將待檃栝、烝矯然後直；鈍金必將待礱厲然後利；今人的性惡，必將待師國家典章法度然後正，得禮正義道義道品德修養規程正義道義然後治，今人無師國家典章法度，則偏險而且不正；無禮正義道義道品德修養規程正義道義，則悖亂而且不治，古的人或事物聖王以人性惡，以為偏險而且不正，悖亂而且不治，是以為的起禮正義道義道品德修養規程正義道義，製國家典章法度度，以矯飾人的情性而且正的，以擾化人的情性而且導的啊，始皆出於治，合於道的人或事物啊。今人的化師國家典章法度，積文學，道禮正義道義道品德修養規程正義道義的人或事物為君子；縱性情，安恣睢，而且違禮正義道義道品德修養規程正義道義的人或事物為小人。用此觀的，人的性惡明矣，他的善的人或事物偽啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故枸木必將待檃栝、烝矯然後直」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故枸木必將待檃栝、烝矯然後直；鈍金必將待礱厲然後利；……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-3\",\"chapterId\":\"xunzi_ch-23\",\"order\":3,\"canonicalText\":\"孟子曰：「人之學者，其性善。」\",\"sentenceIds\":[\"xunzi_ch-23_p-3_s-1\",\"xunzi_ch-23_p-3_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孟子說道：人的學的人或事物，他的性善。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孟子曰：「人之學者，其性善」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孟子曰：「人之學者，其性善。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-4\",\"chapterId\":\"xunzi_ch-23\",\"order\":4,\"canonicalText\":\"曰：是不然。是不及知人之性，而不察乎人之性偽之分者也。凡性者，天之就也，不可學，不可事。禮義者，聖人之所生也，人之所學而能，所事而成者也。不可學，不可事，而在人者，謂之性；可學而能，可事而成之在人者，謂之偽。是性偽之分也。今人之性，目可以見，耳可以聽；夫可以見之明不離目，可以聽之聰不離耳，目明而耳聰，不可學明矣。\",\"sentenceIds\":[\"xunzi_ch-23_p-4_s-1\",\"xunzi_ch-23_p-4_s-2\",\"xunzi_ch-23_p-4_s-3\",\"xunzi_ch-23_p-4_s-4\",\"xunzi_ch-23_p-4_s-5\",\"xunzi_ch-23_p-4_s-6\",\"xunzi_ch-23_p-4_s-7\",\"xunzi_ch-23_p-4_s-8\",\"xunzi_ch-23_p-4_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：是不然。是不及知人的性，而且不察乎人的性偽的分的人或事物啊。凡性的人或事物，天的就啊，不可學，不可事。禮正義道義道品德修養規程正義道義的人或事物，聖人的所生啊，人的所學而且能，所事而且成的人或事物啊。不可學，不可事，而且在人的人或事物，謂的性；可學而且能，可事而且成的在人的人或事物，謂的偽。是性偽的分啊。今人的性，目可以見，耳可以聽；夫可以見的明不離目，可以聽的聰不離耳，目明而且耳聰，不可學明矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：是不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：是不然。是不及知人之性，而不察乎人之性偽之分者也……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-5\",\"chapterId\":\"xunzi_ch-23\",\"order\":5,\"canonicalText\":\"孟子曰：「今人之性善，將皆失喪其性故也。」\",\"sentenceIds\":[\"xunzi_ch-23_p-5_s-1\",\"xunzi_ch-23_p-5_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孟子說道：今人的性善，將皆失喪他的性所以啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孟子曰：「今人之性善，將皆失喪其性故也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孟子曰：「今人之性善，將皆失喪其性故也。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-6\",\"chapterId\":\"xunzi_ch-23\",\"order\":6,\"canonicalText\":\"曰：若是則過矣。今人之性，生而離其樸，離其資，必失而喪之。用此觀之，然則人之性惡明矣。所謂性善者，不離其樸而美之，不離其資而利之也。使夫資樸之於美，心意之於善，若夫可以見之明不離目，可以聽之聰不離耳，故曰目明而耳聰也。今人之性，飢而欲飽，寒而欲煖，勞而欲休，此人之情性也。今人見長而不敢先食者，將有所讓也；勞而不敢求息者，將有所代也。夫子之讓乎父，弟之讓乎兄，子之代乎父，弟之代乎兄，此二行者，皆反於性而悖於情也；然而孝子之道，禮義之文理也。故順情性則不辭讓矣，辭讓則悖於情性矣。用此觀之，人之性惡明矣，其善者偽也。\",\"sentenceIds\":[\"xunzi_ch-23_p-6_s-1\",\"xunzi_ch-23_p-6_s-2\",\"xunzi_ch-23_p-6_s-3\",\"xunzi_ch-23_p-6_s-4\",\"xunzi_ch-23_p-6_s-5\",\"xunzi_ch-23_p-6_s-6\",\"xunzi_ch-23_p-6_s-7\",\"xunzi_ch-23_p-6_s-8\",\"xunzi_ch-23_p-6_s-9\",\"xunzi_ch-23_p-6_s-10\",\"xunzi_ch-23_p-6_s-11\",\"xunzi_ch-23_p-6_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：若是則過矣。今人的性，生而且離他的樸，離他的資，必失而且喪的。用此觀的，然則人的性惡明矣。所謂性善的人或事物，不離他的樸而且美的，不離他的資而且利的啊。使夫資樸的於美，心意的於善，至於談到那可以見的明不離目，可以聽的聰不離耳，所以古聖先賢說道：目明而且耳聰啊。今人的性，飢而且欲飽，寒而且欲煖，勞而且欲休，此人的情性啊。今人見長而且不敢先食的人或事物，將有所讓啊；勞而且不敢求息的人或事物，將有所代啊。夫子的讓乎父，弟的讓乎兄，子的代乎父，弟的代乎兄，此二行的人或事物，皆反於性而且悖於情啊；然而且孝子的道，禮正義道義道品德修養規程正義道義的文理啊。所以順情性則不辭讓矣，辭讓則悖於情性矣。用此觀的，人的性惡明矣，他的善的人或事物偽啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：若是則過矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：若是則過矣。今人之性，生而離其樸，離其資，必失而……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-7\",\"chapterId\":\"xunzi_ch-23\",\"order\":7,\"canonicalText\":\"問者曰：「人之性惡，則禮義惡生？」\",\"sentenceIds\":[\"xunzi_ch-23_p-7_s-1\",\"xunzi_ch-23_p-7_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"問的人或事物說道：人的性惡，則禮正義道義道品德修養規程正義道義惡生？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「問者曰：「人之性惡，則禮義惡生」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「問者曰：「人之性惡，則禮義惡生？」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-8\",\"chapterId\":\"xunzi_ch-23\",\"order\":8,\"canonicalText\":\"應之曰：凡禮義者，是生於聖人之偽，非故生於人之性也。故陶人埏埴而為器，然則器生於陶人之偽，非故生於人之性也。故工人斲木而成器，然則器生於工人之偽，非故生於人之性也。聖人積思慮，習偽故，以生禮義而起法度，然則禮義法度者，是生於聖人之偽，非故生於人之性也。若夫目好色，耳好聽，口好味，心好利，骨體膚理好愉佚，是皆生於人之情性者也；感而自然，不待事而後生之者也。夫感而不能然，必且待事而後然者，謂之生於偽。是性偽之所生，其不同之徵也。\",\"sentenceIds\":[\"xunzi_ch-23_p-8_s-1\",\"xunzi_ch-23_p-8_s-2\",\"xunzi_ch-23_p-8_s-3\",\"xunzi_ch-23_p-8_s-4\",\"xunzi_ch-23_p-8_s-5\",\"xunzi_ch-23_p-8_s-6\",\"xunzi_ch-23_p-8_s-7\",\"xunzi_ch-23_p-8_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"應的說道：凡禮正義道義道品德修養規程正義道義的人或事物，是生於聖人的偽，絕不是所以生於人的性啊。所以陶人埏埴而且為器，然則器生於陶人的偽，絕不是所以生於人的性啊。所以工人斲木而且成器，然則器生於工人的偽，絕不是所以生於人的性啊。聖人積思慮，習偽所以，以生禮正義道義道品德修養規程正義道義而且起國家典章法度度，然則禮正義道義道品德修養規程正義道義國家典章法度度的人或事物，是生於聖人的偽，絕不是所以生於人的性啊。至於談到那目好色，耳好聽，口好味，心好利，骨體膚理好愉佚，是皆生於人的情性的人或事物啊；感而且自然，不待事而且後生的的人或事物啊。夫感而且不能然，必且待事而且後然的人或事物，謂的生於偽。是性偽的所生，他的不同的徵啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「應之曰：凡禮義者，是生於聖人之偽，非故生於人之性也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「應之曰：凡禮義者，是生於聖人之偽，非故生於人之性也。……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-9\",\"chapterId\":\"xunzi_ch-23\",\"order\":9,\"canonicalText\":\"故聖人化性而起偽，偽起而生禮義，禮義生而製法度；然則禮義法度者，是聖人之所生也。故聖人之所以同於眾，其不異於眾者，性也；所以異而過眾者，偽也。夫好利而欲得者，此人之情性也。假之有弟兄資財而分者，且順情性，好利而欲得，若是，則兄弟相拂奪矣；且化禮義之文理，若是，則讓乎國人矣。故順情性則弟兄爭矣，化禮義則讓乎國人矣。\",\"sentenceIds\":[\"xunzi_ch-23_p-9_s-1\",\"xunzi_ch-23_p-9_s-2\",\"xunzi_ch-23_p-9_s-3\",\"xunzi_ch-23_p-9_s-4\",\"xunzi_ch-23_p-9_s-5\",\"xunzi_ch-23_p-9_s-6\",\"xunzi_ch-23_p-9_s-7\",\"xunzi_ch-23_p-9_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以聖人化性而且起偽，偽起而且生禮正義道義道品德修養規程正義道義，禮正義道義道品德修養規程正義道義生而且製國家典章法度度；然則禮正義道義道品德修養規程正義道義國家典章法度度的人或事物，是聖人的所生啊。所以聖人的所以同於眾，他的不異於眾的人或事物，性啊；所以異而且過眾的人或事物，偽啊。夫好利而且欲得的人或事物，此人的情性啊。假的有弟兄資財而且分的人或事物，且順情性，好利而且欲得，若是，則兄弟相拂奪矣；且化禮正義道義道品德修養規程正義道義的文理，若是，則讓乎國人矣。所以順情性則弟兄爭矣，化禮正義道義道品德修養規程正義道義則讓乎國人矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故聖人化性而起偽，偽起而生禮義，禮義生而製法度」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故聖人化性而起偽，偽起而生禮義，禮義生而製法度；然則……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-10\",\"chapterId\":\"xunzi_ch-23\",\"order\":10,\"canonicalText\":\"凡人之慾為善者，為性惡也。夫薄願厚，惡願美，狹願廣，貧願富，賤願貴，苟無之中者，必求於外。故富而不願財，貴而不願埶，苟有之中者，必不及於外。用此觀之，人之慾為善者，為性惡也。今人之性，固無禮義，故彊學而求有之也；性不知禮義，故思慮而求知之也。然則性而已，則人無禮義，不知禮義。人無禮義則亂，不知禮義則悖。然則性而已，則悖亂在己。用此觀之，人之性惡明矣，其善者偽也。\",\"sentenceIds\":[\"xunzi_ch-23_p-10_s-1\",\"xunzi_ch-23_p-10_s-2\",\"xunzi_ch-23_p-10_s-3\",\"xunzi_ch-23_p-10_s-4\",\"xunzi_ch-23_p-10_s-5\",\"xunzi_ch-23_p-10_s-6\",\"xunzi_ch-23_p-10_s-7\",\"xunzi_ch-23_p-10_s-8\",\"xunzi_ch-23_p-10_s-9\",\"xunzi_ch-23_p-10_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡人的慾為善的人或事物，為性惡啊。夫薄願厚，惡願美，狹願廣，貧願富，賤願貴，苟無的中的人或事物，必求於外。所以富而且不願財，貴而且不願埶，苟有的中的人或事物，必不及於外。用此觀的，人的慾為善的人或事物，為性惡啊。今人的性，固無禮正義道義道品德修養規程正義道義，所以彊學而且求有的啊；性不知禮正義道義道品德修養規程正義道義，所以思慮而且求知的啊。然則性而且已，則人無禮正義道義道品德修養規程正義道義，不知禮正義道義道品德修養規程正義道義。人無禮正義道義道品德修養規程正義道義則亂，不知禮正義道義道品德修養規程正義道義則悖。然則性而且已，則悖亂在己。用此觀的，人的性惡明矣，他的善的人或事物偽啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡人之慾為善者，為性惡也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡人之慾為善者，為性惡也。夫薄願厚，惡願美，狹願廣，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-11\",\"chapterId\":\"xunzi_ch-23\",\"order\":11,\"canonicalText\":\"孟子曰：「人之性善。」\",\"sentenceIds\":[\"xunzi_ch-23_p-11_s-1\",\"xunzi_ch-23_p-11_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孟子說道：人的性善。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孟子曰：「人之性善」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孟子曰：「人之性善。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-12\",\"chapterId\":\"xunzi_ch-23\",\"order\":12,\"canonicalText\":\"曰：是不然。凡古今天下之所謂善者，正理平治也；所謂惡者，偏險悖亂也：是善惡之分也矣。今誠以人之性固正理平治邪，則有惡用聖王，惡用禮義哉？雖有聖王禮義，將曷加於正理平治也哉？今不然，人之性惡。故古者聖人以人之性惡，以為偏險而不正，悖亂而不治，故為之立君上之埶以臨之，明禮義以化之，起法正以治之，重刑罰以禁之，使天下皆出於治，合於善也。是聖王之治而禮義之化也。今當試去君上之埶，無禮義之化，去法正之治，無刑罰之禁，倚而觀天下民人之相與也。若是，則夫彊者害弱而奪之，眾者暴寡而譁之，天下悖亂而相亡，不待頃矣。用此觀之，然則人之性惡明矣，其善者偽也。\",\"sentenceIds\":[\"xunzi_ch-23_p-12_s-1\",\"xunzi_ch-23_p-12_s-2\",\"xunzi_ch-23_p-12_s-3\",\"xunzi_ch-23_p-12_s-4\",\"xunzi_ch-23_p-12_s-5\",\"xunzi_ch-23_p-12_s-6\",\"xunzi_ch-23_p-12_s-7\",\"xunzi_ch-23_p-12_s-8\",\"xunzi_ch-23_p-12_s-9\",\"xunzi_ch-23_p-12_s-10\",\"xunzi_ch-23_p-12_s-11\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：是不然。凡古今天下的所謂善的人或事物，正理平治啊；所謂惡的人或事物，偏險悖亂啊：是善惡的分啊矣。今誠以人的性固正理平治邪，則有惡用聖王，惡用禮正義道義道品德修養規程正義道義哉？雖有聖王禮正義道義道品德修養規程正義道義，將曷加於正理平治啊哉？今不然，人的性惡。所以古的人或事物聖人以人的性惡，以為偏險而且不正，悖亂而且不治，所以為的立君上的埶以臨的，明禮正義道義道品德修養規程正義道義以化的，起國家典章法度正以治的，重刑罰以禁的，使天下皆出於治，合於善啊。是聖王的治而且禮正義道義道品德修養規程正義道義的化啊。今當試去君上的埶，無禮正義道義道品德修養規程正義道義的化，去國家典章法度正的治，無刑罰的禁，倚而且觀天下民人的相與啊。若是，則夫彊的人或事物害弱而且奪的，眾的人或事物暴寡而且譁的，天下悖亂而且相亡，不待頃矣。用此觀的，然則人的性惡明矣，他的善的人或事物偽啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：是不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：是不然。凡古今天下之所謂善者，正理平治也；所謂惡……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-13\",\"chapterId\":\"xunzi_ch-23\",\"order\":13,\"canonicalText\":\"故善言古者，必有節於今；善言天者，必有徵於人。凡論者貴其有辨合，有符驗。故坐而言之，起而可設，張而可施行。今孟子曰：「人之性善。」無辨合符驗，坐而言之，起而不可設，張而不可施行，豈不過甚矣哉！故性善則去聖王，息禮義矣。性惡則與聖王，貴禮義矣。故檃栝之生，為枸木也；繩墨之起，為不直也；立君上，明禮義，為性惡也。用此觀之，然則人之性惡明矣，其善者偽也。\",\"sentenceIds\":[\"xunzi_ch-23_p-13_s-1\",\"xunzi_ch-23_p-13_s-2\",\"xunzi_ch-23_p-13_s-3\",\"xunzi_ch-23_p-13_s-4\",\"xunzi_ch-23_p-13_s-5\",\"xunzi_ch-23_p-13_s-6\",\"xunzi_ch-23_p-13_s-7\",\"xunzi_ch-23_p-13_s-8\",\"xunzi_ch-23_p-13_s-9\",\"xunzi_ch-23_p-13_s-10\",\"xunzi_ch-23_p-13_s-11\",\"xunzi_ch-23_p-13_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以善言古的人或事物，必有節於今；善言天的人或事物，必有徵於人。凡論的人或事物貴他的有辨合，有符驗。所以坐而且言的，起而且可設，張而且可施行。今孟子說道：人的性善。無辨合符驗，坐而且言的，起而且不可設，張而且不可施行，豈不過甚矣哉！所以性善則去聖王，息禮正義道義道品德修養規程正義道義矣。性惡則與聖王，貴禮正義道義道品德修養規程正義道義矣。所以檃栝的生，為枸木啊；繩墨的起，為不直啊；立君上，明禮正義道義道品德修養規程正義道義，為性惡啊。用此觀的，然則人的性惡明矣，他的善的人或事物偽啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 13 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故善言古者，必有節於今」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故善言古者，必有節於今；善言天者，必有徵於人。凡論者……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-14\",\"chapterId\":\"xunzi_ch-23\",\"order\":14,\"canonicalText\":\"直木不待檃栝而直者，其性直也。枸木必將待檃栝烝矯然後直者，以其性不直也。今人之性惡，必將待聖王之治，禮義之化，然後始出於治，合於善也。用此觀之，人之性惡明矣，其善者偽也。\",\"sentenceIds\":[\"xunzi_ch-23_p-14_s-1\",\"xunzi_ch-23_p-14_s-2\",\"xunzi_ch-23_p-14_s-3\",\"xunzi_ch-23_p-14_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"直木不待檃栝而且直的人或事物，他的性直啊。枸木必將待檃栝烝矯然後直的人或事物，以他的性不直啊。今人的性惡，必將待聖王的治，禮正義道義道品德修養規程正義道義的化，然後始出於治，合於善啊。用此觀的，人的性惡明矣，他的善的人或事物偽啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 14 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「直木不待檃栝而直者，其性直也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「直木不待檃栝而直者，其性直也。枸木必將待檃栝烝矯然後……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-15\",\"chapterId\":\"xunzi_ch-23\",\"order\":15,\"canonicalText\":\"問者曰：「禮義積偽者，是人之性，故聖人能生之也。」\",\"sentenceIds\":[\"xunzi_ch-23_p-15_s-1\",\"xunzi_ch-23_p-15_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"問的人或事物說道：禮正義道義道品德修養規程正義道義積偽的人或事物，是人的性，所以聖人能生的啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 15 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「問者曰：「禮義積偽者，是人之性，故聖人能生之也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「問者曰：「禮義積偽者，是人之性，故聖人能生之也。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-16\",\"chapterId\":\"xunzi_ch-23\",\"order\":16,\"canonicalText\":\"應之曰：是不然。夫陶人埏埴而生瓦，然則瓦埴豈陶人之性也哉？工人斲木而生器，然則器木豈工人之性也哉？夫聖人之於禮義也，闢則陶埏而生之也。然則禮義積偽者，豈人之本性也哉！凡人之性者，堯舜之與桀蹠，其性一也；君子之與小人，其性一也。今將以禮義積偽為人之性邪？然則有曷貴堯禹，曷貴君子矣哉！凡貴堯禹君子者，能化性，能起偽，偽起而生禮義。然則聖人之於禮義積偽也，亦猶陶埏而為之也。用此觀之，然則禮義積偽者，豈人之性也哉！所賤於桀蹠小人者，從其性，順其情，安恣睢，以出乎貪利爭奪。故人之性惡明矣，其善者偽也。天非私曾騫孝己而外眾人也，然而曾騫孝己獨厚於孝之實，而全於孝之名者，何也？以綦於禮義故也。天非私齊魯之民而外秦人也，然而於父子之義，夫婦之別，不如齊魯之孝具敬文者，何也？以秦人從情性，安恣睢，慢於禮義故也，豈其性異矣哉！\",\"sentenceIds\":[\"xunzi_ch-23_p-16_s-1\",\"xunzi_ch-23_p-16_s-2\",\"xunzi_ch-23_p-16_s-3\",\"xunzi_ch-23_p-16_s-4\",\"xunzi_ch-23_p-16_s-5\",\"xunzi_ch-23_p-16_s-6\",\"xunzi_ch-23_p-16_s-7\",\"xunzi_ch-23_p-16_s-8\",\"xunzi_ch-23_p-16_s-9\",\"xunzi_ch-23_p-16_s-10\",\"xunzi_ch-23_p-16_s-11\",\"xunzi_ch-23_p-16_s-12\",\"xunzi_ch-23_p-16_s-13\",\"xunzi_ch-23_p-16_s-14\",\"xunzi_ch-23_p-16_s-15\",\"xunzi_ch-23_p-16_s-16\",\"xunzi_ch-23_p-16_s-17\",\"xunzi_ch-23_p-16_s-18\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"應的說道：是不然。夫陶人埏埴而且生瓦，然則瓦埴豈陶人的性啊哉？工人斲木而且生器，然則器木豈工人的性啊哉？夫聖人的於禮正義道義道品德修養規程正義道義啊，闢則陶埏而且生的啊。然則禮正義道義道品德修養規程正義道義積偽的人或事物，豈人的本性啊哉！凡人的性的人或事物，堯舜的與桀蹠，他的性一啊；君子的與小人，他的性一啊。今將以禮正義道義道品德修養規程正義道義積偽為人的性邪？然則有曷貴堯禹，曷貴君子矣哉！凡貴堯禹君子的人或事物，能化性，能起偽，偽起而且生禮正義道義道品德修養規程正義道義。然則聖人的於禮正義道義道品德修養規程正義道義積偽啊，亦猶陶埏而且為的啊。用此觀的，然則禮正義道義道品德修養規程正義道義積偽的人或事物，豈人的性啊哉！所賤於桀蹠小人的人或事物，從他的性，順他的情，安恣睢，以出乎貪利爭奪。所以人的性惡明矣，他的善的人或事物偽啊。天絕不是私曾騫孝己而且外眾人啊，然而且曾騫孝己獨厚於孝的實，而且全於孝的名的人或事物，何啊？以綦於禮正義道義道品德修養規程正義道義所以啊。天絕不是私齊魯的民而且外秦人啊，然而且於父子的正義道義，夫婦的別，不如齊魯的孝具敬文的人或事物，何啊？以秦人從情性，安恣睢，慢於禮正義道義道品德修養規程正義道義所以啊，豈他的性異矣哉！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 16 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「應之曰：是不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「應之曰：是不然。夫陶人埏埴而生瓦，然則瓦埴豈陶人之性……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-17\",\"chapterId\":\"xunzi_ch-23\",\"order\":17,\"canonicalText\":\"「塗之人可以為禹。」曷謂也？\",\"sentenceIds\":[\"xunzi_ch-23_p-17_s-1\",\"xunzi_ch-23_p-17_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"塗的人可以為禹。曷謂啊？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 17 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「「塗之人可以為禹」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「「塗之人可以為禹。」曷謂也？」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-18\",\"chapterId\":\"xunzi_ch-23\",\"order\":18,\"canonicalText\":\"曰：凡禹之所以為禹者，以其為仁義法正也。然則仁義法正有可知可能之理。然而塗之人也，皆有可以知仁義法正之質，皆有可以能仁義法正之具，然則其可以為禹明矣。今以仁義法正為固無可知可能之理邪？然則唯禹不知仁義法正，不能仁義法正也。將使塗之人固無可以知仁義法正之質，而固無可以能仁義法正之具邪？然則塗之人也，且內不可以知父子之義，外不可以知君臣之正。今不然。塗之人者，皆內可以知父子之義，外可以知君臣之正，然則其可以知之質，可以能之具，其在塗之人明矣。今使塗之人者，以其可以知之質，可以能之具，本夫仁義法正之可知可能之理，可能之具，然則其可以為禹明矣。今使塗之人伏術為學，專心一志，思索孰察，加日縣久，積善而不息，則通於神明，參於天地矣。故聖人者，人之所積而致矣。\",\"sentenceIds\":[\"xunzi_ch-23_p-18_s-1\",\"xunzi_ch-23_p-18_s-2\",\"xunzi_ch-23_p-18_s-3\",\"xunzi_ch-23_p-18_s-4\",\"xunzi_ch-23_p-18_s-5\",\"xunzi_ch-23_p-18_s-6\",\"xunzi_ch-23_p-18_s-7\",\"xunzi_ch-23_p-18_s-8\",\"xunzi_ch-23_p-18_s-9\",\"xunzi_ch-23_p-18_s-10\",\"xunzi_ch-23_p-18_s-11\",\"xunzi_ch-23_p-18_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：凡禹的所以為禹的人或事物，以他的為仁愛慈悲之德正義道義國家典章法度正啊。然則仁愛慈悲之德正義道義國家典章法度正有可知可能的理。然而且塗的人啊，皆有可以知仁愛慈悲之德正義道義國家典章法度正的質，皆有可以能仁愛慈悲之德正義道義國家典章法度正的具，然則他的可以為禹明矣。今以仁愛慈悲之德正義道義國家典章法度正為固無可知可能的理邪？然則唯禹不知仁愛慈悲之德正義道義國家典章法度正，不能仁愛慈悲之德正義道義國家典章法度正啊。將使塗的人固無可以知仁愛慈悲之德正義道義國家典章法度正的質，而且固無可以能仁愛慈悲之德正義道義國家典章法度正的具邪？然則塗的人啊，且內不可以知父子的正義道義，外不可以知君臣的正。今不然。塗的人的人或事物，皆內可以知父子的正義道義，外可以知君臣的正，然則他的可以知的質，可以能的具，他的在塗的人明矣。今使塗的人的人或事物，以他的可以知的質，可以能的具，本夫仁愛慈悲之德正義道義國家典章法度正的可知可能的理，可能的具，然則他的可以為禹明矣。今使塗的人伏術為學，專心一志，思索孰察，加日縣久，積善而且不息，則通於神明，參於天地矣。所以聖人的人或事物，人的所積而且致矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 18 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：凡禹之所以為禹者，以其為仁義法正也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：凡禹之所以為禹者，以其為仁義法正也。然則仁義法正……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-19\",\"chapterId\":\"xunzi_ch-23\",\"order\":19,\"canonicalText\":\"曰：「聖可積而致，然而皆不可積，何也？」\",\"sentenceIds\":[\"xunzi_ch-23_p-19_s-1\",\"xunzi_ch-23_p-19_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：聖可積而且致，然而且皆不可積，何啊？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 19 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：「聖可積而致，然而皆不可積，何也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：「聖可積而致，然而皆不可積，何也？」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-20\",\"chapterId\":\"xunzi_ch-23\",\"order\":20,\"canonicalText\":\"曰：可以而不可使也。故小人可以為君子，而不肯為君子；君子可以為小人，而不肯為小人。小人君子者，未嘗不可以相為也，然而不相為者，可以而不可使也。故塗之人可以為禹，則然；塗之人能為禹，則未必然也。雖不能為禹，無害可以為禹。足可以遍行天下，然而未嘗有遍行天下者也。夫工匠農賈，未嘗不可以相為事也，然而未嘗能相為事也。用此觀之，然則可以為，未必能也；雖不能，無害可以為。然則能不能之與可不可，其不同遠矣，其不可以相為明矣。\",\"sentenceIds\":[\"xunzi_ch-23_p-20_s-1\",\"xunzi_ch-23_p-20_s-2\",\"xunzi_ch-23_p-20_s-3\",\"xunzi_ch-23_p-20_s-4\",\"xunzi_ch-23_p-20_s-5\",\"xunzi_ch-23_p-20_s-6\",\"xunzi_ch-23_p-20_s-7\",\"xunzi_ch-23_p-20_s-8\",\"xunzi_ch-23_p-20_s-9\",\"xunzi_ch-23_p-20_s-10\",\"xunzi_ch-23_p-20_s-11\",\"xunzi_ch-23_p-20_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：可以而且不可使啊。所以小人可以為君子，而且不肯為君子；君子可以為小人，而且不肯為小人。小人君子的人或事物，未嘗不可以相為啊，然而且不相為的人或事物，可以而且不可使啊。所以塗的人可以為禹，則然；塗的人能為禹，則未必然啊。雖不能為禹，無害可以為禹。足可以遍行天下，然而且未嘗有遍行天下的人或事物啊。夫工匠農賈，未嘗不可以相為事啊，然而且未嘗能相為事啊。用此觀的，然則可以為，未必能啊；雖不能，無害可以為。然則能不能的與可不可，他的不同遠矣，他的不可以相為明矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 20 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：可以而不可使也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：可以而不可使也。故小人可以為君子，而不肯為君子；……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-21\",\"chapterId\":\"xunzi_ch-23\",\"order\":21,\"canonicalText\":\"堯問於舜曰：「人情何如？」舜對曰：「人情甚不美，又何問焉！妻子具而孝衰於親，嗜慾得而信衰於友，爵祿盈而忠衰於君。人之情乎！人之情乎！甚不美，又何問焉！唯賢者為不然。」\",\"sentenceIds\":[\"xunzi_ch-23_p-21_s-1\",\"xunzi_ch-23_p-21_s-2\",\"xunzi_ch-23_p-21_s-3\",\"xunzi_ch-23_p-21_s-4\",\"xunzi_ch-23_p-21_s-5\",\"xunzi_ch-23_p-21_s-6\",\"xunzi_ch-23_p-21_s-7\",\"xunzi_ch-23_p-21_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"堯問於舜說道：人情何如？舜對說道：人情甚不美，又何問焉！妻子具而且孝衰於親，嗜慾得而且信衰於友，爵祿盈而且忠衰於君。人的情乎！甚不美，又何問焉！唯賢的人或事物為不然。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 21 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「堯問於舜曰：「人情何如」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「堯問於舜曰：「人情何如？」舜對曰：「人情甚不美，又何……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-22\",\"chapterId\":\"xunzi_ch-23\",\"order\":22,\"canonicalText\":\"有聖人之知者，有士君子之知者，有小人之知者，有役夫之知者。多言則文而類，終日議其所以，言之千舉萬變，其統類一也：是聖人之知也。少言則徑而省，論而法，若佚之以繩：是士君子之知也。其言也諂，其行也悖，其舉事多悔：是小人之知也。齊給便敏而無類，雜能旁魄而無用，析速粹孰而不急，不恤是非，不論曲直，以期勝人為意，是役夫之知也。\",\"sentenceIds\":[\"xunzi_ch-23_p-22_s-1\",\"xunzi_ch-23_p-22_s-2\",\"xunzi_ch-23_p-22_s-3\",\"xunzi_ch-23_p-22_s-4\",\"xunzi_ch-23_p-22_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"有聖人的知的人或事物，有士君子的知的人或事物，有小人的知的人或事物，有役夫的知的人或事物。多言則文而且類，終日議他的所以，言的千舉萬變，他的統類一啊：是聖人的知啊。少言則徑而且省，論而且國家典章法度，若佚的以繩：是士君子的知啊。他的言啊諂，他的行啊悖，他的舉事多悔：是小人的知啊。齊給便敏而且無類，雜能旁魄而且無用，析速粹孰而且不急，不恤是絕不是，不論曲直，以期勝人為意，是役夫的知啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 22 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「有聖人之知者，有士君子之知者，有小人之知者，有役夫之知者」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「有聖人之知者，有士君子之知者，有小人之知者，有役夫之……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-23\",\"chapterId\":\"xunzi_ch-23\",\"order\":23,\"canonicalText\":\"有上勇者，有中勇者，有下勇者。天下有中，敢直其身；先王有道，敢行其意；上不循於亂世之君，下不俗於亂世之民；仁之所在無貧窮，仁之所亡無富貴；天下知之，則欲與天下同苦樂之；天下不知之，則傀然獨立天地之間而不畏：是上勇也。禮恭而意儉，大齊信焉，而輕貨財；賢者敢推而尚之，不肖者敢援而廢之：是中勇也。輕身而重貨，恬禍而廣解苟免，不恤是非然不然之情，以期勝人為意：是下勇也。\",\"sentenceIds\":[\"xunzi_ch-23_p-23_s-1\",\"xunzi_ch-23_p-23_s-2\",\"xunzi_ch-23_p-23_s-3\",\"xunzi_ch-23_p-23_s-4\",\"xunzi_ch-23_p-23_s-5\",\"xunzi_ch-23_p-23_s-6\",\"xunzi_ch-23_p-23_s-7\",\"xunzi_ch-23_p-23_s-8\",\"xunzi_ch-23_p-23_s-9\",\"xunzi_ch-23_p-23_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"有上勇的人或事物，有中勇的人或事物，有下勇的人或事物。天下有中，敢直他的身；先王有道，敢行他的意；上不循於亂世的君，下不俗於亂世的民；仁愛慈悲之德的所在無貧窮，仁愛慈悲之德的所亡無富貴；天下知的，則欲與天下同苦樂的；天下不知的，則傀然獨立天地的間而且不畏：是上勇啊。禮正義道義道品德修養規程恭而且意儉，大齊信焉，而且輕貨財；賢的人或事物敢推而且尚的，不肖的人或事物敢援而且廢的：是中勇啊。輕身而且重貨，恬禍而且廣解苟免，不恤是絕不是然不然的情，以期勝人為意：是下勇啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 23 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「有上勇者，有中勇者，有下勇者」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「有上勇者，有中勇者，有下勇者。天下有中，敢直其身；先……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-23_p-24\",\"chapterId\":\"xunzi_ch-23\",\"order\":24,\"canonicalText\":\"繁弱、鉅黍古之良弓也；然而不得排檠則不能自正。桓公之蔥，太公之闕，文王之錄，莊君之曶，闔閭之幹將、莫邪、鉅闕、闢閭，此皆古之良劍也；然而不加砥厲則不能利，不得人力則不能斷。驊騮、騹驥、纖離、綠耳，此皆古之良馬也；然而必前有銜轡之制，後有鞭策之威，加之以造父之駛，然後一日而致千里也。夫人雖有性質美而心辯知，必將求賢師而事之，擇良友而友之。得賢師而事之，則所聞者堯舜禹湯之道也；得良友而友之，則所見者忠信敬讓之行也。身日進於仁義而不自知也者，靡使然也。今與不善人處，則所聞者欺誣詐偽也，所見者汙漫淫邪貪利之行也，身且加於刑戮而不自知者，靡使然也。傳曰：「不知其子視其友，不知其君視其左右。」靡而已矣！靡而已矣！\",\"sentenceIds\":[\"xunzi_ch-23_p-24_s-1\",\"xunzi_ch-23_p-24_s-2\",\"xunzi_ch-23_p-24_s-3\",\"xunzi_ch-23_p-24_s-4\",\"xunzi_ch-23_p-24_s-5\",\"xunzi_ch-23_p-24_s-6\",\"xunzi_ch-23_p-24_s-7\",\"xunzi_ch-23_p-24_s-8\",\"xunzi_ch-23_p-24_s-9\",\"xunzi_ch-23_p-24_s-10\",\"xunzi_ch-23_p-24_s-11\",\"xunzi_ch-23_p-24_s-12\",\"xunzi_ch-23_p-24_s-13\",\"xunzi_ch-23_p-24_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"繁弱、鉅黍古的良弓啊；然而且不得排檠則不能自正。桓公的蔥，太公的闕，文王的錄，莊君的曶，闔閭的幹將、莫邪、鉅闕、闢閭，此皆古的良劍啊；然而且不加砥厲則不能利，不得人力則不能斷。驊騮、騹驥、纖離、綠耳，此皆古的良馬啊；然而且必前有銜轡的制，後有鞭策的威，加的以造父的駛，然後一日而且致千里啊。夫人雖有性質美而且心辯知，必將求賢師而且事的，擇良友而且友的。得賢師而且事的，則所聞的人或事物堯舜禹湯的道啊；得良友而且友的，則所見的人或事物忠信敬讓的行啊。身日進於仁愛慈悲之德正義道義而且不自知啊的人或事物，靡使然啊。今與不善人處，則所聞的人或事物欺誣詐偽啊，所見的人或事物汙漫淫邪貪利的行啊，身且加於刑戮而且不自知的人或事物，靡使然啊。傳說道：不知他的子視他的友，不知他的君視他的左右。靡而且已矣！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈性惡〉（第 24 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「繁弱、鉅黍古之良弓也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「繁弱、鉅黍古之良弓也；然而不得排檠則不能自正。桓公之……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"xunzi_ch-23_p-1_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-1\",\"order\":1,\"canonicalText\":\"人之性惡，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-1_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-1\",\"order\":2,\"canonicalText\":\"今人之性，生而有好利焉，順是，故爭奪生而辭讓亡焉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-1_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-1\",\"order\":3,\"canonicalText\":\"生而有疾惡焉，順是，故殘賊生而忠信亡焉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-1_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-1\",\"order\":4,\"canonicalText\":\"生而有耳目之欲，有好聲色焉，順是，故淫亂生而禮義文理亡焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-1_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-1\",\"order\":5,\"canonicalText\":\"然則從人之性，順人之情，必出於爭奪，合於犯分亂理，而歸於暴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-1_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-1\",\"order\":6,\"canonicalText\":\"故必將有師法之化，禮義之道，然後出於辭讓，合於文理，而歸於治。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-1_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-1\",\"order\":7,\"canonicalText\":\"用此觀之，人之性惡明矣，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-2_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-2\",\"order\":1,\"canonicalText\":\"故枸木必將待檃栝、烝矯然後直；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-2_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-2\",\"order\":2,\"canonicalText\":\"鈍金必將待礱厲然後利；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-2_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-2\",\"order\":3,\"canonicalText\":\"今人之性惡，必將待師法然後正，得禮義然後治，今人無師法，則偏險而不正；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-2_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-2\",\"order\":4,\"canonicalText\":\"無禮義，則悖亂而不治，古者聖王以人性惡，以為偏險而不正，悖亂而不治，是以為之起禮義，製法度，以矯飾人之情性而正之，以擾化人之情性而導之也，始皆出於治，合於道者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-2_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-2\",\"order\":5,\"canonicalText\":\"今人之化師法，積文學，道禮義者為君子；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-2_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-2\",\"order\":6,\"canonicalText\":\"縱性情，安恣睢，而違禮義者為小人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-2_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-2\",\"order\":7,\"canonicalText\":\"用此觀之，人之性惡明矣，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-3_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-3\",\"order\":1,\"canonicalText\":\"孟子曰：「人之學者，其性善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-3_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-3\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":1,\"canonicalText\":\"曰：是不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":2,\"canonicalText\":\"是不及知人之性，而不察乎人之性偽之分者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":3,\"canonicalText\":\"凡性者，天之就也，不可學，不可事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":4,\"canonicalText\":\"禮義者，聖人之所生也，人之所學而能，所事而成者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":5,\"canonicalText\":\"不可學，不可事，而在人者，謂之性；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":6,\"canonicalText\":\"可學而能，可事而成之在人者，謂之偽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":7,\"canonicalText\":\"是性偽之分也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":8,\"canonicalText\":\"今人之性，目可以見，耳可以聽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-4_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-4\",\"order\":9,\"canonicalText\":\"夫可以見之明不離目，可以聽之聰不離耳，目明而耳聰，不可學明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-5_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-5\",\"order\":1,\"canonicalText\":\"孟子曰：「今人之性善，將皆失喪其性故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-5_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-5\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":1,\"canonicalText\":\"曰：若是則過矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":2,\"canonicalText\":\"今人之性，生而離其樸，離其資，必失而喪之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":3,\"canonicalText\":\"用此觀之，然則人之性惡明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":4,\"canonicalText\":\"所謂性善者，不離其樸而美之，不離其資而利之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":5,\"canonicalText\":\"使夫資樸之於美，心意之於善，若夫可以見之明不離目，可以聽之聰不離耳，故曰目明而耳聰也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":6,\"canonicalText\":\"今人之性，飢而欲飽，寒而欲煖，勞而欲休，此人之情性也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":7,\"canonicalText\":\"今人見長而不敢先食者，將有所讓也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":8,\"canonicalText\":\"勞而不敢求息者，將有所代也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":9,\"canonicalText\":\"夫子之讓乎父，弟之讓乎兄，子之代乎父，弟之代乎兄，此二行者，皆反於性而悖於情也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":10,\"canonicalText\":\"然而孝子之道，禮義之文理也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":11,\"canonicalText\":\"故順情性則不辭讓矣，辭讓則悖於情性矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-6_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-6\",\"order\":12,\"canonicalText\":\"用此觀之，人之性惡明矣，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-7_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-7\",\"order\":1,\"canonicalText\":\"問者曰：「人之性惡，則禮義惡生？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-7_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-7\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-8_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-8\",\"order\":1,\"canonicalText\":\"應之曰：凡禮義者，是生於聖人之偽，非故生於人之性也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-8_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-8\",\"order\":2,\"canonicalText\":\"故陶人埏埴而為器，然則器生於陶人之偽，非故生於人之性也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-8_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-8\",\"order\":3,\"canonicalText\":\"故工人斲木而成器，然則器生於工人之偽，非故生於人之性也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-8_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-8\",\"order\":4,\"canonicalText\":\"聖人積思慮，習偽故，以生禮義而起法度，然則禮義法度者，是生於聖人之偽，非故生於人之性也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-8_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-8\",\"order\":5,\"canonicalText\":\"若夫目好色，耳好聽，口好味，心好利，骨體膚理好愉佚，是皆生於人之情性者也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-8_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-8\",\"order\":6,\"canonicalText\":\"感而自然，不待事而後生之者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-8_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-8\",\"order\":7,\"canonicalText\":\"夫感而不能然，必且待事而後然者，謂之生於偽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-8_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-8\",\"order\":8,\"canonicalText\":\"是性偽之所生，其不同之徵也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-9_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-9\",\"order\":1,\"canonicalText\":\"故聖人化性而起偽，偽起而生禮義，禮義生而製法度；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-9_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-9\",\"order\":2,\"canonicalText\":\"然則禮義法度者，是聖人之所生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-9_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-9\",\"order\":3,\"canonicalText\":\"故聖人之所以同於眾，其不異於眾者，性也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-9_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-9\",\"order\":4,\"canonicalText\":\"所以異而過眾者，偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-9_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-9\",\"order\":5,\"canonicalText\":\"夫好利而欲得者，此人之情性也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-9_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-9\",\"order\":6,\"canonicalText\":\"假之有弟兄資財而分者，且順情性，好利而欲得，若是，則兄弟相拂奪矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-9_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-9\",\"order\":7,\"canonicalText\":\"且化禮義之文理，若是，則讓乎國人矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-9_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-9\",\"order\":8,\"canonicalText\":\"故順情性則弟兄爭矣，化禮義則讓乎國人矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":1,\"canonicalText\":\"凡人之慾為善者，為性惡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":2,\"canonicalText\":\"夫薄願厚，惡願美，狹願廣，貧願富，賤願貴，苟無之中者，必求於外。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":3,\"canonicalText\":\"故富而不願財，貴而不願埶，苟有之中者，必不及於外。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":4,\"canonicalText\":\"用此觀之，人之慾為善者，為性惡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":5,\"canonicalText\":\"今人之性，固無禮義，故彊學而求有之也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":6,\"canonicalText\":\"性不知禮義，故思慮而求知之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":7,\"canonicalText\":\"然則性而已，則人無禮義，不知禮義。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":8,\"canonicalText\":\"人無禮義則亂，不知禮義則悖。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":9,\"canonicalText\":\"然則性而已，則悖亂在己。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-10_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-10\",\"order\":10,\"canonicalText\":\"用此觀之，人之性惡明矣，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-11_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-11\",\"order\":1,\"canonicalText\":\"孟子曰：「人之性善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-11_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-11\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":1,\"canonicalText\":\"曰：是不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":2,\"canonicalText\":\"凡古今天下之所謂善者，正理平治也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":3,\"canonicalText\":\"所謂惡者，偏險悖亂也：是善惡之分也矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":4,\"canonicalText\":\"今誠以人之性固正理平治邪，則有惡用聖王，惡用禮義哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":5,\"canonicalText\":\"雖有聖王禮義，將曷加於正理平治也哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":6,\"canonicalText\":\"今不然，人之性惡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":7,\"canonicalText\":\"故古者聖人以人之性惡，以為偏險而不正，悖亂而不治，故為之立君上之埶以臨之，明禮義以化之，起法正以治之，重刑罰以禁之，使天下皆出於治，合於善也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":8,\"canonicalText\":\"是聖王之治而禮義之化也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":9,\"canonicalText\":\"今當試去君上之埶，無禮義之化，去法正之治，無刑罰之禁，倚而觀天下民人之相與也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":10,\"canonicalText\":\"若是，則夫彊者害弱而奪之，眾者暴寡而譁之，天下悖亂而相亡，不待頃矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-12_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-12\",\"order\":11,\"canonicalText\":\"用此觀之，然則人之性惡明矣，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":1,\"canonicalText\":\"故善言古者，必有節於今；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":2,\"canonicalText\":\"善言天者，必有徵於人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":3,\"canonicalText\":\"凡論者貴其有辨合，有符驗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":4,\"canonicalText\":\"故坐而言之，起而可設，張而可施行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":5,\"canonicalText\":\"今孟子曰：「人之性善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":6,\"canonicalText\":\"」無辨合符驗，坐而言之，起而不可設，張而不可施行，豈不過甚矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":7,\"canonicalText\":\"故性善則去聖王，息禮義矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":8,\"canonicalText\":\"性惡則與聖王，貴禮義矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":9,\"canonicalText\":\"故檃栝之生，為枸木也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":10,\"canonicalText\":\"繩墨之起，為不直也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":11,\"canonicalText\":\"立君上，明禮義，為性惡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-13_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-13\",\"order\":12,\"canonicalText\":\"用此觀之，然則人之性惡明矣，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-14_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-14\",\"order\":1,\"canonicalText\":\"直木不待檃栝而直者，其性直也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-14_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-14\",\"order\":2,\"canonicalText\":\"枸木必將待檃栝烝矯然後直者，以其性不直也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-14_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-14\",\"order\":3,\"canonicalText\":\"今人之性惡，必將待聖王之治，禮義之化，然後始出於治，合於善也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-14_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-14\",\"order\":4,\"canonicalText\":\"用此觀之，人之性惡明矣，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-15_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-15\",\"order\":1,\"canonicalText\":\"問者曰：「禮義積偽者，是人之性，故聖人能生之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-15_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-15\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":1,\"canonicalText\":\"應之曰：是不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":2,\"canonicalText\":\"夫陶人埏埴而生瓦，然則瓦埴豈陶人之性也哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":3,\"canonicalText\":\"工人斲木而生器，然則器木豈工人之性也哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":4,\"canonicalText\":\"夫聖人之於禮義也，闢則陶埏而生之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":5,\"canonicalText\":\"然則禮義積偽者，豈人之本性也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":6,\"canonicalText\":\"凡人之性者，堯舜之與桀蹠，其性一也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":7,\"canonicalText\":\"君子之與小人，其性一也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":8,\"canonicalText\":\"今將以禮義積偽為人之性邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":9,\"canonicalText\":\"然則有曷貴堯禹，曷貴君子矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":10,\"canonicalText\":\"凡貴堯禹君子者，能化性，能起偽，偽起而生禮義。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":11,\"canonicalText\":\"然則聖人之於禮義積偽也，亦猶陶埏而為之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":12,\"canonicalText\":\"用此觀之，然則禮義積偽者，豈人之性也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":13,\"canonicalText\":\"所賤於桀蹠小人者，從其性，順其情，安恣睢，以出乎貪利爭奪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":14,\"canonicalText\":\"故人之性惡明矣，其善者偽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":15,\"canonicalText\":\"天非私曾騫孝己而外眾人也，然而曾騫孝己獨厚於孝之實，而全於孝之名者，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":16,\"canonicalText\":\"以綦於禮義故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":17,\"canonicalText\":\"天非私齊魯之民而外秦人也，然而於父子之義，夫婦之別，不如齊魯之孝具敬文者，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-16_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-16\",\"order\":18,\"canonicalText\":\"以秦人從情性，安恣睢，慢於禮義故也，豈其性異矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-17_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-17\",\"order\":1,\"canonicalText\":\"「塗之人可以為禹。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-17_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-17\",\"order\":2,\"canonicalText\":\"」曷謂也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":1,\"canonicalText\":\"曰：凡禹之所以為禹者，以其為仁義法正也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":2,\"canonicalText\":\"然則仁義法正有可知可能之理。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":3,\"canonicalText\":\"然而塗之人也，皆有可以知仁義法正之質，皆有可以能仁義法正之具，然則其可以為禹明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":4,\"canonicalText\":\"今以仁義法正為固無可知可能之理邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":5,\"canonicalText\":\"然則唯禹不知仁義法正，不能仁義法正也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":6,\"canonicalText\":\"將使塗之人固無可以知仁義法正之質，而固無可以能仁義法正之具邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":7,\"canonicalText\":\"然則塗之人也，且內不可以知父子之義，外不可以知君臣之正。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":8,\"canonicalText\":\"今不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":9,\"canonicalText\":\"塗之人者，皆內可以知父子之義，外可以知君臣之正，然則其可以知之質，可以能之具，其在塗之人明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":10,\"canonicalText\":\"今使塗之人者，以其可以知之質，可以能之具，本夫仁義法正之可知可能之理，可能之具，然則其可以為禹明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":11,\"canonicalText\":\"今使塗之人伏術為學，專心一志，思索孰察，加日縣久，積善而不息，則通於神明，參於天地矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-18_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-18\",\"order\":12,\"canonicalText\":\"故聖人者，人之所積而致矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-19_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-19\",\"order\":1,\"canonicalText\":\"曰：「聖可積而致，然而皆不可積，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-19_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-19\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":1,\"canonicalText\":\"曰：可以而不可使也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":2,\"canonicalText\":\"故小人可以為君子，而不肯為君子；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":3,\"canonicalText\":\"君子可以為小人，而不肯為小人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":4,\"canonicalText\":\"小人君子者，未嘗不可以相為也，然而不相為者，可以而不可使也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":5,\"canonicalText\":\"故塗之人可以為禹，則然；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":6,\"canonicalText\":\"塗之人能為禹，則未必然也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":7,\"canonicalText\":\"雖不能為禹，無害可以為禹。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":8,\"canonicalText\":\"足可以遍行天下，然而未嘗有遍行天下者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":9,\"canonicalText\":\"夫工匠農賈，未嘗不可以相為事也，然而未嘗能相為事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":10,\"canonicalText\":\"用此觀之，然則可以為，未必能也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":11,\"canonicalText\":\"雖不能，無害可以為。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-20_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-20\",\"order\":12,\"canonicalText\":\"然則能不能之與可不可，其不同遠矣，其不可以相為明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-21_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-21\",\"order\":1,\"canonicalText\":\"堯問於舜曰：「人情何如？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-21_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-21\",\"order\":2,\"canonicalText\":\"」舜對曰：「人情甚不美，又何問焉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-21_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-21\",\"order\":3,\"canonicalText\":\"妻子具而孝衰於親，嗜慾得而信衰於友，爵祿盈而忠衰於君。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-21_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-21\",\"order\":4,\"canonicalText\":\"人之情乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-21_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-21\",\"order\":5,\"canonicalText\":\"人之情乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-21_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-21\",\"order\":6,\"canonicalText\":\"甚不美，又何問焉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-21_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-21\",\"order\":7,\"canonicalText\":\"唯賢者為不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-21_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-21\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-22_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-22\",\"order\":1,\"canonicalText\":\"有聖人之知者，有士君子之知者，有小人之知者，有役夫之知者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-22_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-22\",\"order\":2,\"canonicalText\":\"多言則文而類，終日議其所以，言之千舉萬變，其統類一也：是聖人之知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-22_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-22\",\"order\":3,\"canonicalText\":\"少言則徑而省，論而法，若佚之以繩：是士君子之知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-22_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-22\",\"order\":4,\"canonicalText\":\"其言也諂，其行也悖，其舉事多悔：是小人之知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-22_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-22\",\"order\":5,\"canonicalText\":\"齊給便敏而無類，雜能旁魄而無用，析速粹孰而不急，不恤是非，不論曲直，以期勝人為意，是役夫之知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":1,\"canonicalText\":\"有上勇者，有中勇者，有下勇者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":2,\"canonicalText\":\"天下有中，敢直其身；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":3,\"canonicalText\":\"先王有道，敢行其意；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":4,\"canonicalText\":\"上不循於亂世之君，下不俗於亂世之民；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":5,\"canonicalText\":\"仁之所在無貧窮，仁之所亡無富貴；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":6,\"canonicalText\":\"天下知之，則欲與天下同苦樂之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":7,\"canonicalText\":\"天下不知之，則傀然獨立天地之間而不畏：是上勇也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":8,\"canonicalText\":\"禮恭而意儉，大齊信焉，而輕貨財；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":9,\"canonicalText\":\"賢者敢推而尚之，不肖者敢援而廢之：是中勇也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-23_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-23\",\"order\":10,\"canonicalText\":\"輕身而重貨，恬禍而廣解苟免，不恤是非然不然之情，以期勝人為意：是下勇也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":1,\"canonicalText\":\"繁弱、鉅黍古之良弓也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":2,\"canonicalText\":\"然而不得排檠則不能自正。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":3,\"canonicalText\":\"桓公之蔥，太公之闕，文王之錄，莊君之曶，闔閭之幹將、莫邪、鉅闕、闢閭，此皆古之良劍也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":4,\"canonicalText\":\"然而不加砥厲則不能利，不得人力則不能斷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":5,\"canonicalText\":\"驊騮、騹驥、纖離、綠耳，此皆古之良馬也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":6,\"canonicalText\":\"然而必前有銜轡之制，後有鞭策之威，加之以造父之駛，然後一日而致千里也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":7,\"canonicalText\":\"夫人雖有性質美而心辯知，必將求賢師而事之，擇良友而友之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":8,\"canonicalText\":\"得賢師而事之，則所聞者堯舜禹湯之道也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":9,\"canonicalText\":\"得良友而友之，則所見者忠信敬讓之行也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":10,\"canonicalText\":\"身日進於仁義而不自知也者，靡使然也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":11,\"canonicalText\":\"今與不善人處，則所聞者欺誣詐偽也，所見者汙漫淫邪貪利之行也，身且加於刑戮而不自知者，靡使然也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":12,\"canonicalText\":\"傳曰：「不知其子視其友，不知其君視其左右。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":13,\"canonicalText\":\"」靡而已矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-23_p-24_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-23\",\"passageId\":\"xunzi_ch-23_p-24\",\"order\":14,\"canonicalText\":\"靡而已矣！\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
